using Register = std::array<uint32_t, 4>;
static unsigned checks = 0;
static void check(bool condition, const char* message) {
  ++checks;
  if (!condition) { throw std::runtime_error(message); }
}

struct FakeDevice {
  using Values = std::array<std::array<Register, 256>, 2>;
  Values values {};
  Values captured {};
  std::array<std::array<bool, 256>, 2> capturedKnown {};
  D3DCAPS9 caps {};
  unsigned calls = 0, capCalls = 0, uploads = 0;
  bool dirty = false, recording = false;
  HRESULT nextResult = S_OK, capsResult = S_OK;
  FakeDevice() { caps.MaxVertexShaderConst = 256; caps.PixelShaderVersion = D3DPS_VERSION(3, 0); }
  HRESULT GetDeviceCaps(D3DCAPS9* output) {
    ++capCalls;
    if (FAILED(capsResult)) { return capsResult; }
    *output = caps;
    return capsResult;
  }
  uint32_t limit(Stage stage) const {
    if (stage == Stage::Vertex) { return caps.MaxVertexShaderConst; }
    const unsigned version = D3DSHADER_VERSION_MAJOR(caps.PixelShaderVersion);
    return version >= 3 ? 224u : version >= 2 ? 32u : version >= 1 ? 8u : 0u;
  }
  HRESULT set(Stage stage, UINT start, const float* data, UINT count) {
    ++calls;
    const HRESULT result = nextResult;
    nextResult = S_OK;
    if (result != S_OK) { return result; }
    const uint32_t softwareLimit = stage == Stage::Vertex ? 8192u : 224u;
    if (start > softwareLimit || count > softwareLimit - start) { return D3DERR_INVALIDCALL; }
    const uint32_t hardwareLimit = limit(stage);
    const uint32_t actual = start < hardwareLimit ? (std::min)(count, hardwareLimit - start) : 0;
    if (actual == 0) { return S_OK; }
    if (!data) { return D3DERR_INVALIDCALL; }
    const size_t slot = stage == Stage::Vertex ? 0u : 1u;
    auto& target = recording ? captured : values;
    std::memcpy(target[slot][start].data(), data, static_cast<size_t>(actual) * 16);
    if (recording) {
      for (uint32_t i = start; i < start + actual; ++i) { capturedKnown[slot][i] = true; }
    } else { dirty = true; }
    return S_OK;
  }
  HRESULT SetVertexShaderConstantF(UINT start, const float* data, UINT count) {
    return set(Stage::Vertex, start, data, count);
  }
  HRESULT SetPixelShaderConstantF(UINT start, const float* data, UINT count) {
    return set(Stage::Pixel, start, data, count);
  }
  void apply() {
    for (size_t stage = 0; stage < values.size(); ++stage) {
      for (size_t reg = 0; reg < values[stage].size(); ++reg) {
        if (capturedKnown[stage][reg]) { values[stage][reg] = captured[stage][reg]; }
      }
    }
    dirty = true;
  }
  void draw() { if (dirty) { ++uploads; dirty = false; } }
};

