static HRESULT send(FakeDevice& device, uint32_t id, Stage stage, uint32_t start,
                    uint32_t count, const float* data, size_t bytes) {
  return setHostFloatConstants(&device, id, stage, start, count, data, bytes,
    [&]() { return device.set(stage, start, data, count); });
}
static void resetHarness() {
  gFloatConstantCache = FloatConstantCache {};
  gVanilla = true; gRemix = false; gResponses = false; gOverlayPresenter = nullptr;
}

static void basicAndBits() {
  resetHarness();
  FakeDevice device;
  std::array<float, 12> values {};
  check(send(device, 1, Stage::Pixel, 0, 1, values.data(), 16) == S_OK && device.calls == 1,
    "first zero write must reach backend");
  device.draw();
  check(send(device, 1, Stage::Pixel, 0, 1, values.data(), 16) == S_OK && device.calls == 1,
    "exact repeat not removed");
  device.draw();
  check(device.uploads == 1, "repeat dirtied fake backend again");
  check(device.capCalls == 1, "caps were queried on hot repeated setters");
  values[5] = 7;
  send(device, 1, Stage::Pixel, 0, 2, values.data(), 32);
  check(device.calls == 2, "partially unknown range was skipped");
  send(device, 1, Stage::Pixel, 1, 1, values.data() + 4, 16);
  check(device.calls == 2, "known subrange was not recognized");
  values[6] = 8;
  send(device, 1, Stage::Pixel, 1, 1, values.data() + 4, 16);
  check(device.calls == 3 && device.values[1][1][2] != 0, "changed overlapping range was lost");
  send(device, 1, Stage::Vertex, 1, 1, values.data() + 4, 16);
  check(device.calls == 4, "VS/PS knowledge leaked");
  const uint32_t bits[] = {0x7fc00001u, 0x80000000u, 0x7f800000u, 0xff800000u};
  std::memcpy(values.data(), bits, 16);
  send(device, 1, Stage::Pixel, 2, 1, values.data(), 16);
  const auto afterBits = device.calls;
  send(device, 1, Stage::Pixel, 2, 1, values.data(), 16);
  check(device.calls == afterBits, "equal NaN payload was not byte-compared");
  values[1] = 0.0f;
  send(device, 1, Stage::Pixel, 2, 1, values.data(), 16);
  check(device.calls == afterBits + 1, "negative/positive zero difference was lost");
  uint32_t differentNaN = 0x7fc00002u;
  std::memcpy(values.data(), &differentNaN, sizeof(differentNaN));
  send(device, 1, Stage::Pixel, 2, 1, values.data(), 16);
  check(device.calls == afterBits + 2, "different NaN payload was skipped");
}

static void errorsAndBounds() {
  resetHarness();
  FakeDevice device;
  std::array<float, 12> data {1, 2, 3, 4};
  device.nextResult = E_FAIL;
  check(send(device, 1, Stage::Pixel, 0, 1, data.data(), 16) == E_FAIL, "error return changed");
  send(device, 1, Stage::Pixel, 0, 1, data.data(), 16);
  check(device.calls == 2, "failed value became known");
  data[0] = 9;
  device.nextResult = S_FALSE;
  check(send(device, 1, Stage::Pixel, 0, 1, data.data(), 16) == S_FALSE, "non-S_OK return changed");
  send(device, 1, Stage::Pixel, 0, 1, data.data(), 16);
  check(device.calls == 4, "non-S_OK value became known");
  check(send(device, 1, Stage::Pixel, UINT32_MAX, 2, data.data(), 32) == D3DERR_INVALIDCALL,
    "overflow range did not reach backend validation");
  check(send(device, 1, Stage::Pixel, 0, 1, nullptr, 0) == D3DERR_INVALIDCALL,
    "null payload did not reach backend validation");
  check(send(device, 1, Stage::Pixel, 0, 0, nullptr, 0) == S_OK, "zero count behavior changed");
  const auto before = device.calls;
  send(device, 1, Stage::Pixel, 0, 1, data.data(), 12);
  send(device, 1, Stage::Pixel, 0, 1, data.data(), 16);
  check(device.calls == before + 2, "mismatched payload length became known");

  resetHarness();
  FakeDevice sm1;
  sm1.caps.PixelShaderVersion = D3DPS_VERSION(1, 1);
  sm1.caps.MaxVertexShaderConst = 96;
  send(sm1, 2, Stage::Pixel, 7, 2, data.data(), 32);
  send(sm1, 2, Stage::Pixel, 7, 2, data.data(), 32);
  check(sm1.calls == 2, "backend-clipped range was cached");
  send(sm1, 2, Stage::Pixel, 7, 1, data.data(), 16);
  send(sm1, 2, Stage::Pixel, 7, 1, data.data(), 16);
  check(sm1.calls == 3, "last legal SM1 register not cached");
  send(sm1, 2, Stage::Vertex, 95, 2, data.data(), 32);
  send(sm1, 2, Stage::Vertex, 95, 2, data.data(), 32);
  check(sm1.calls == 5, "VS caps clamp was ignored");

  resetHarness();
  FakeDevice unknown;
  unknown.capsResult = E_FAIL;
  send(unknown, 3, Stage::Pixel, 0, 1, data.data(), 16);
  send(unknown, 3, Stage::Pixel, 0, 1, data.data(), 16);
  check(unknown.calls == 2, "unknown caps allowed filtering");
}

static void lifetimeAndPolicies() {
  resetHarness();
  FakeDevice a, b;
  float data[] = {1, 2, 3, 4};
  send(a, 1, Stage::Vertex, 0, 1, data, 16);
  send(b, 2, Stage::Vertex, 0, 1, data, 16);
  send(a, 1, Stage::Vertex, 0, 1, data, 16);
  check(a.calls == 2 && b.calls == 1, "device switch leaked values");
  gFloatConstantCache.destroyDevice(1);
  FakeDevice replacement;
  send(replacement, 1, Stage::Vertex, 0, 1, data, 16);
  check(replacement.calls == 1, "reused device ID inherited values");
  for (int policy = 0; policy < 4; ++policy) {
    gVanilla = policy != 0; gRemix = policy == 1; gResponses = policy == 2;
    gOverlayPresenter = policy == 3 ? &replacement : nullptr;
    const auto before = replacement.calls;
    send(replacement, 1, Stage::Vertex, 0, 1, data, 16);
    send(replacement, 1, Stage::Vertex, 0, 1, data, 16);
    check(replacement.calls == before + 2, "special observation policy filtered backend calls");
  }
  gVanilla = true; gRemix = false; gResponses = false; gOverlayPresenter = nullptr;
  const auto before = replacement.calls;
  send(replacement, 1, Stage::Vertex, 0, 1, data, 16);
  check(replacement.calls == before + 1, "bypassed value remained known");
  gFloatConstantCache.invalidate(); // Failed Reset.
  send(replacement, 1, Stage::Vertex, 0, 1, data, 16);
  gFloatConstantCache.invalidate(); // Successful Reset; recording is handled independently.
  send(replacement, 1, Stage::Vertex, 0, 1, data, 16);
  check(replacement.calls == before + 3, "reset success/failure did not invalidate");
  gFloatConstantCache.invalidate(); // Apply, shader switch, SWVP and Present boundary.
  send(replacement, 1, Stage::Vertex, 0, 1, data, 16);
  check(replacement.calls == before + 4, "external state boundary did not invalidate");
}

static void recordingAcrossDevices() {
  resetHarness();
  FakeDevice a, b;
  float normal[] = {1, 2, 3, 4}, recorded[] = {5, 6, 7, 8};
  send(a, 1, Stage::Pixel, 0, 1, normal, 16);
  a.recording = true; gFloatConstantCache.beginRecording(1, true);
  send(a, 1, Stage::Pixel, 0, 1, recorded, 16);
  send(a, 1, Stage::Pixel, 0, 1, recorded, 16);
  check(a.calls == 3 && a.values[1][0][0] != a.captured[1][0][0], "recording altered normal state or skipped calls");
  b.recording = true; gFloatConstantCache.beginRecording(2, true);
  a.recording = false; gFloatConstantCache.endRecording(1, true);
  const auto before = a.calls;
  send(a, 1, Stage::Pixel, 0, 1, normal, 16);
  send(a, 1, Stage::Pixel, 0, 1, normal, 16);
  check(a.calls == before + 2, "recording on another device was forgotten");
  gFloatConstantCache.endRecording(2, false);
  send(a, 1, Stage::Pixel, 0, 1, normal, 16);
  check(a.calls == before + 3, "failed End stopped bypassing recording");
  gFloatConstantCache.invalidate(); // Successful Reset/ResetEx need not end backend recording.
  send(a, 1, Stage::Pixel, 0, 1, normal, 16);
  send(a, 1, Stage::Pixel, 0, 1, normal, 16);
  check(a.calls == before + 5, "Reset boundary forgot recording on another device");
  b.recording = false; gFloatConstantCache.endRecording(2, true);
  send(a, 1, Stage::Pixel, 0, 1, normal, 16);
  send(a, 1, Stage::Pixel, 0, 1, normal, 16);
  check(a.calls == before + 6, "successful End did not restore fresh caching");
  gFloatConstantCache.invalidate(); a.apply();
  send(a, 1, Stage::Pixel, 0, 1, normal, 16);
  check(a.calls == before + 7 && a.values[1][0][0] != a.captured[1][0][0], "Apply stale value was skipped");
  gFloatConstantCache.beginRecording(2, true);
  gFloatConstantCache.destroyDevice(2);
  send(a, 1, Stage::Pixel, 0, 1, normal, 16);
  send(a, 1, Stage::Pixel, 0, 1, normal, 16);
  check(a.calls == before + 8, "destroyed recording device left cache permanently bypassed");
  gFloatConstantCache.beginRecording(3, false);
  send(a, 1, Stage::Pixel, 0, 1, normal, 16);
  send(a, 1, Stage::Pixel, 0, 1, normal, 16);
  check(a.calls == before + 9, "failed Begin entered recording mode");
}

// Feed serialized scalar/blob payloads to the actual two Host case bodies.
// This proves a skipped backend call does not skip reading its wire payload.
struct Reader {
  std::vector<uint32_t> words;
  size_t position = 0;
  uint32_t scalar() {
    if (position >= words.size()) { throw std::runtime_error("payload scalar overread"); }
    return words[position++];
  }
  uint32_t blob(void** data) {
    const uint32_t bytes = scalar();
    const size_t size = (static_cast<size_t>(bytes) + 3) / 4;
    if (size > words.size() - position) { throw std::runtime_error("payload blob overread"); }
    *data = bytes ? words.data() + position : nullptr;
    position += size;
    return bytes;
  }
  void constant(uint32_t uid, uint32_t start, uint32_t count, const float* data) {
    words.insert(words.end(), {uid, start, count, count * 16});
    const auto previous = words.size();
    words.resize(previous + static_cast<size_t>(count) * 4);
    std::memcpy(words.data() + previous, data, static_cast<size_t>(count) * 16);
  }
};
static Reader reader;
struct DeviceBridge {
  static uint32_t get_data() { return reader.scalar(); }
  static uint32_t get_data(void** data) { return reader.blob(data); }
};
