enum Opcode { IDirect3DDevice9Ex_SetVertexShaderConstantF, IDirect3DDevice9Ex_SetPixelShaderConstantF };
struct Header { Opcode command; uint32_t pHandle; };
static std::unordered_map<uint32_t, FakeDevice*> gpD3DDevices;
static unsigned responses = 0;
#define GET_RES(name, map) const auto name##Handle = rpcHeader.pHandle; auto* name = map.at(name##Handle)
#define PULL_U(name) const UINT name = DeviceBridge::get_data()
#define PULL_DATA(size, name) const uint32_t name##_len = DeviceBridge::get_data(reinterpret_cast<void**>(&name)); \
  check(name##_len == 0 || (size) == name##_len, "actual handler payload size assertion failed")
#define SEND_OPTIONAL_SERVER_RESPONSE(result, uid) \
  { lastResult = (result); if (GlobalOptions::getSendAllServerResponses()) { ++responses; check((uid) != 0, "lost UID"); } }
static HRESULT dispatch(Header rpcHeader) {
  PULL_U(currentUID);
  HRESULT lastResult = E_FAIL;
  switch (rpcHeader.command) {
#include "constant_cache_host_cases.inc"
  }
  return lastResult;
}
#undef GET_RES
#undef PULL_U
#undef PULL_DATA
#undef SEND_OPTIONAL_SERVER_RESPONSE

static void payloadConsumption() {
  resetHarness();
  FakeDevice device;
  gpD3DDevices = {{7, &device}};
  reader = Reader{}; responses = 0;
  float data[] = {1, 2, 3, 4, 5, 6, 7, 8};
  reader.constant(101, 3, 2, data);
  const auto firstEnd = reader.words.size();
  reader.constant(102, 3, 2, data);
  const auto secondEnd = reader.words.size();
  reader.constant(103, 3, 2, data);
  const auto thirdEnd = reader.words.size();
  reader.words.insert(reader.words.end(), {104, 0x12345678, 0x87654321});
  check(dispatch({IDirect3DDevice9Ex_SetPixelShaderConstantF, 7}) == S_OK && reader.position == firstEnd,
    "first actual PS handler did not consume its full packet");
  check(dispatch({IDirect3DDevice9Ex_SetPixelShaderConstantF, 7}) == S_OK && reader.position == secondEnd && device.calls == 1,
    "skipped PS backend call did not consume its full packet");
  check(dispatch({IDirect3DDevice9Ex_SetVertexShaderConstantF, 7}) == S_OK && reader.position == thirdEnd && device.calls == 2,
    "actual VS handler did not consume its full packet");
  check(reader.scalar() == 104 && reader.scalar() == 0x12345678 && reader.scalar() == 0x87654321 && reader.position == reader.words.size(),
    "following command UID or payload was shifted");
  check(responses == 0, "async policy invented a response");
  reader = Reader{}; gResponses = true;
  reader.constant(105, 3, 2, data); reader.constant(106, 3, 2, data);
  dispatch({IDirect3DDevice9Ex_SetPixelShaderConstantF, 7});
  dispatch({IDirect3DDevice9Ex_SetPixelShaderConstantF, 7});
  check(device.calls == 4 && responses == 2, "synchronous response mode skipped an actual handler call");
}

static void modelReplay() {
  resetHarness();
  FakeDevice filtered, reference;
  std::array<float, 16> payload {};
  for (uint32_t iteration = 0; iteration < 1000; ++iteration) {
    const auto stage = iteration % 3 ? Stage::Pixel : Stage::Vertex;
    const uint32_t start = (iteration / 2) % 16;
    const uint32_t count = 1 + (iteration / 8) % 4;
    if (iteration % 2 == 0) {
      for (size_t value = 0; value < payload.size(); ++value) { payload[value] = static_cast<float>(iteration + value); }
    }
    if (iteration % 37 == 0) { gFloatConstantCache.invalidate(); }
    const auto actual = send(filtered, 1, stage, start, count, payload.data(), static_cast<size_t>(count) * 16);
    const auto expected = reference.set(stage, start, payload.data(), count);
    check(actual == expected && filtered.values == reference.values, "filtered stream diverged from reference device state");
    filtered.draw(); reference.draw();
  }
  check(filtered.calls < reference.calls && filtered.uploads < reference.uploads,
    "model stream did not avoid any real backend updates/uploads");
}

int main() {
  try {
    basicAndBits(); errorsAndBounds(); lifetimeAndPolicies(); recordingAcrossDevices(); payloadConsumption(); modelReplay();
    std::printf("Host float constant cache: %u checks passed; actual Host setter/payload cases included\n", checks);
    return 0;
  } catch (const std::exception& error) {
    std::fprintf(stderr, "Host float constant cache failed: %s\n", error.what());
    return 1;
  }
}
